package surfaces

// Ports packages/chord/src/surfaces/format.ts. Pi's formatNumber and formatTime are `Intl.NumberFormat` and
// `Intl.DateTimeFormat` with the current language's locale; outside a render the platform's default locale applies. Go
// has no current language (D450): the language is the first parameter, nil outside a render.
//
// Both print what the pinned Node prints, byte for byte. Go has no CLDR of that vintage (golang.org/x/text is CLDR 32,
// rounds half-even and has no date patterns), so the output comes from tables generated by running the pinned Node's
// Intl over every locale ICU has data for (intl_gen.go, automation/gen/generate-intl-tables.mjs, `make intl-tables`);
// the closed option types (NumberOptions, TimeOptions) are the shapes the tables cover, and intl_drift_test.go diffs
// the tables against a live Node.

// FormatNumber is value in language's locale (`1.234,5` in German); nil language: the platform's default locale. It
// returns the errors `Intl` throws (an option out of range, minimum fraction digits above the maximum, a tag that is
// not a language tag) as ErrOption / ErrLocale.
func FormatNumber(lang *Language, value float64, options *NumberOptions) (string, error) {
	// pig divergence (D464): a closed option type and tables generated from the pinned Node's Intl, not Intl's open options.
	// pig divergence (D466): no per-language formatter cache; a format is a table lookup.
	minFD, maxFD, err := options.fractionDigits()
	if err != nil {
		return "", err
	}
	var tag string
	if lang != nil {
		tag = lang.Locale
	} else {
		tag = platformLocale()
	}
	format, err := numberFormatOf(tag)
	if err != nil {
		return "", err
	}
	var buf [64]byte
	return string(format.appendNumber(buf[:0], value, minFD, maxFD)), nil
}
